-- ============================================================
-- AUTO-MINT CARDS FOR ALL ACTIVE CASES
-- ============================================================
-- Per BUILD_PLAN Section 4.3: Deterministic minting formulas
-- power = impact * 2
-- rarity = legendary if impact=5, rare if impact=4, uncommon if impact=3, else common
-- faction = heaven if good_votes >= evil_votes, else hell

INSERT INTO cards (
  case_id, name, category, impact, power, rarity, faction,
  alignment_ratio, art_seed, source_url, art_url
)
SELECT 
  uc.id,
  uc.title,
  COALESCE(uc.category, 'Uncategorized'),
  COALESCE(uc.impact, 3),
  COALESCE(uc.impact, 3) * 2,
  CASE 
    WHEN COALESCE(uc.impact, 3) = 5 THEN 'legendary'
    WHEN COALESCE(uc.impact, 3) = 4 THEN 'rare'
    WHEN COALESCE(uc.impact, 3) = 3 THEN 'uncommon'
    ELSE 'common'
  END,
  CASE 
    WHEN COALESCE(uc.good_votes, 0) >= COALESCE(uc.evil_votes, 0) THEN 'heaven'
    ELSE 'hell'
  END,
  COALESCE(uc.good_votes, 0)::numeric / GREATEST(COALESCE(uc.good_votes, 0) + COALESCE(uc.evil_votes, 0), 1),
  encode(sha256(uc.id::text::bytea), 'hex'),
  COALESCE(uc.source_url, ''),
  'pending'
FROM use_cases uc
WHERE uc.status = 'active'
  AND NOT EXISTS (SELECT 1 FROM cards c WHERE c.case_id = uc.id);

-- Report counts
DO $$
DECLARE
  case_count INTEGER;
  card_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO case_count FROM use_cases WHERE status = 'active';
  SELECT COUNT(*) INTO card_count FROM cards;
  RAISE NOTICE 'Seeded % active cases, % cards total', case_count, card_count;
END $$;

